\begin{align*} \begin{vmatrix} a - c & b - d \\ c & d \end{vmatrix} &= (a - c) \begin{vmatrix} d \end{vmatrix} - (b - d) \begin{vmatrix} c \end{vmatrix} \\ &= (a - c)(d) - (b - d)(c) \\ &= ad - cd - bc + dc \\ &= (ad - cd) - (bc - dc) \\ &= a(d - c) - (b - d)c \\ &= ad - ac - bc + cd \\ &= \begin{vmatrix} a & b \\ c & d \end{vmatrix} \\ &= \boxed{5} \end{align*}
